def __repr__(self):
    result = "<{}.{}".format(self.__class__.__module__,
                             self.__class__.__qualname__)
    try:
        name = self.name
    except AttributeError:
        pass
    else:
        result += " name={0!r}".format(name)
    try:
        mode = self.mode
    except AttributeError:
        pass
    else:
        result += " mode={0!r}".format(mode)
    return result + " encoding={0!r}>".format(self.encoding)

